    check('compass actual environment counts',sum(a not in old and b not in old for a,b,_ in edges)==106,f'actual E-only=106; reference E-only={106-len(env_ext)}')
    for eps in (.8,.1):
        nominal=eps/(512*(THETA+1));eta=eps/(64*(THETA+1));trans=eps*nominal/(1536*(THETA+1));g=4*nominal
        upper_t=(THETA+eps/64)/nominal
