    for M in (3,60_000_000_000_000_000):
        heads=M+112;blocks=M+138+heads
        check(f'static bias exact finite inventory M={M}',blocks==2*M+250,f'heads={heads}; qubits={M+116}; blocks={blocks}; distinct pairs={M+120}')
    for t in (.4,2.1):
        h=np.array([[.3,-.2],[-.2,.5]])
